// Generated by scripts/build-edge.mjs from the existing validated API handlers.
import { createClient } from 'npm:@supabase/supabase-js@2';
import { createDatabaseAdapter } from './adapter.mjs';

export async function dispatch(req: Request,user: {id:string},client: any){
const getChatGPTUser=async()=>({userId:'supabase:'+user.id});
const env={DB:createDatabaseAdapter(client,user.id)};
const routes: Record<string,any>={};
routes['/planner']=(()=>{



const json = (data: unknown,status=200) => Response.json(data,{status,headers:{'Cache-Control':'private, no-store'}});
async function GET(){
 const user=await getChatGPTUser(); if(!user)return json({error:'Sign in to save your planner.'},401);
 try {const row=await env.DB.prepare('SELECT state, revision FROM planners WHERE user_id = ?').bind(user.userId).first<{state:string,revision:number}>();
 return json({state:row?JSON.parse(row.state):null,revision:row?.revision??0,userKey:user.userId});}catch{return json({error:'Could not load the planner. Your device copy is safe.'},503)}
}
async function POST(req:Request){
 const user=await getChatGPTUser();if(!user)return json({error:'Sign in to save your planner.'},401);
 if(req.headers.get('origin')!==new URL(req.url).origin)return json({error:'Invalid origin'},403);
 if(!req.headers.get('content-type')?.includes('application/json'))return json({error:'JSON required'},415);
 try{
 const raw=await req.text();if(raw.length>1500000)return json({error:'Planner is too large; export a backup.'},413);
 const {state,revision}=JSON.parse(raw);
 if(!Number.isInteger(revision)||revision<0||!state||!Array.isArray(state.tasks)||!Array.isArray(state.events)||state.tasks.length>3000||state.events.length>3000||typeof state.dump!=='string'||!/^\d{2}:\d{2}$/.test(state.start)||!/^\d{2}:\d{2}$/.test(state.end)||!Number.isFinite(state.buffer)||state.buffer<0||state.buffer>120)return json({error:'Invalid planner data'},400);
 if(state.tasks.some((t:any)=>typeof t.id!=='string'||typeof t.title!=='string'||t.title.length>1000||!Number.isFinite(t.duration)||t.duration<5||t.duration>720||!/^\d{4}-\d{2}-\d{2}$/.test(t.date)||(t.at!=null&&(!Number.isFinite(t.at)||t.at<0||t.at+t.duration>1440)))||state.events.some((e:any)=>typeof e.id!=='string'||typeof e.title!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(e.date)||!Number.isFinite(e.start)||!Number.isFinite(e.end)||e.start<0||e.end>1440||e.end<=e.start))return json({error:'Invalid task or commitment'},400);
 const validTime=(v:any)=>v==null||v===''||(typeof v==='string'&&/^([01]\d|2[0-3]):[0-5]\d$/.test(v));
 if(state.tasks.some((t:any)=>!validTime(t.opens)||!validTime(t.closes)||[t.travelBefore,t.travelAfter].some(n=>n!=null&&(!Number.isFinite(n)||n<0||n>720))))return json({error:'Invalid business hours or journey time'},400);
 const payload=JSON.stringify(state),now=new Date().toISOString();let result;
 if(revision===0)result=await env.DB.prepare('INSERT INTO planners (user_id,state,revision,updated_at) VALUES (?,?,1,?) ON CONFLICT(user_id) DO NOTHING').bind(user.userId,payload,now).run();
 else result=await env.DB.prepare('UPDATE planners SET state = ?, revision = revision + 1, updated_at = ? WHERE user_id = ? AND revision = ?').bind(payload,now,user.userId,revision).run();
 if(result.meta.changes!==1)return json({error:'Your planner changed in another tab or device. Reload before saving.'},409);
 return json({revision:revision+1});
 }catch{return json({error:'Unable to save right now. Your device copy is safe.'},503)}
}

return {GET,POST};})();
routes['/addresses']=(()=>{


async function GET(req:Request){
 if(!await getChatGPTUser())return Response.json({error:'Sign in to search addresses.'},{status:401});
 const params=new URL(req.url).searchParams;const q=params.get('q')?.trim()??'';
 if(q.length<3||q.length>200)return Response.json({results:[]});
 try{
 const url=new URL('https://photon.komoot.io/api/');url.searchParams.set('q',q);url.searchParams.set('limit','5');url.searchParams.set('lang','en');const lat=Number(params.get('lat')??40.85),lon=Number(params.get('lon')??-74.02);if(Number.isFinite(lat)&&Math.abs(lat)<=90&&Number.isFinite(lon)&&Math.abs(lon)<=180){url.searchParams.set('lat',String(lat));url.searchParams.set('lon',String(lon));url.searchParams.set('location_bias_scale','0.5')}
 const res=await fetch(url,{headers:{'Accept':'application/json','User-Agent':'LittleByLittlePlanner/1.0'},signal:AbortSignal.timeout(7000)});
 if(!res.ok)throw Error();const data=await res.json() as any;
 const results=(data.features??[]).slice(0,5).map((f:any)=>{const p=f.properties;const street=[p.housenumber,p.street].filter(Boolean).join(' ');return {name:p.name||street,osmType:p.osm_type,osmId:p.osm_id,label:[p.name!==p.street?p.name:null,street,p.city||p.town||p.village,p.state,p.postcode,p.country].filter(Boolean).join(', '),lat:f.geometry.coordinates[1],lon:f.geometry.coordinates[0]}});
 return Response.json({results},{headers:{'Cache-Control':'private, max-age=120'}});
 }catch{return Response.json({error:'Address search is unavailable. You can still type an address.'},{status:503,headers:{'Cache-Control':'no-store'}})}
}

return {GET};})();
routes['/journey']=(()=>{


async function POST(req:Request){
 if(!await getChatGPTUser())return Response.json({error:'Sign in to plan your journey.'},{status:401});
 if(req.headers.get('origin')!==new URL(req.url).origin)return Response.json({error:'Invalid origin'},{status:403});
 try{const {points}=await req.json();if(!Array.isArray(points)||points.length<2||points.length>40||points.some(p=>!p||!Number.isFinite(p.lat)||!Number.isFinite(p.lon)||Math.abs(p.lat)>90||Math.abs(p.lon)>180))return Response.json({error:'Choose valid places for up to 39 stops.'},{status:400});
 const url='https://router.project-osrm.org/table/v1/driving/'+points.map(p=>`${p.lon},${p.lat}`).join(';')+'?annotations=duration';
 const r=await fetch(url,{headers:{Accept:'application/json'},signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error();const d=await r.json() as any;
 if(d.code!=='Ok'||d.durations?.length!==points.length||d.durations.some((row:any)=>!Array.isArray(row)||row.length!==points.length))throw Error();
 return Response.json({minutes:d.durations.map((row:any[])=>row.map(n=>n==null?null:Math.max(0,Math.ceil(n/60)))),source:'OSRM',trafficAware:false,checkedAt:new Date().toISOString()},{headers:{'Cache-Control':'private, no-store'}});
 }catch{return Response.json({error:'Couldn’t calculate the routes. Your saved plan has not changed. Try again shortly.'},{status:503})}
}

return {POST};})();
routes['/travel']=(()=>{


async function POST(req: Request) {
 if (!await getChatGPTUser()) return Response.json({error:'Sign in to estimate your journey.'},{status:401});
 if(req.headers.get('origin')!==new URL(req.url).origin)return Response.json({error:'Invalid origin'},{status:403});
 try {
 const {origin,destination}=await req.json();
 const valid=(p:any)=>p&&Number.isFinite(p.lat)&&Math.abs(p.lat)<=90&&Number.isFinite(p.lon)&&Math.abs(p.lon)<=180;
 if(!valid(origin)||!valid(destination))return Response.json({error:'Select a starting address and destination from the suggestions first.'},{status:400});
 const coordinates=`${origin.lon},${origin.lat};${destination.lon},${destination.lat};${origin.lon},${origin.lat}`;
 const r=await fetch('https://router.project-osrm.org/route/v1/driving/'+coordinates+'?overview=false&steps=false',{headers:{Accept:'application/json'},signal:AbortSignal.timeout(9000)});
 if(!r.ok)throw Error();const data=await r.json() as any;
 const legs=data.routes?.[0]?.legs;if(data.code!=='Ok'||legs?.length!==2||legs.some((l:any)=>!Number.isFinite(l.duration)))throw Error();
 return Response.json({outbound:Math.max(1,Math.ceil(legs[0].duration/60)),inbound:Math.max(1,Math.ceil(legs[1].duration/60)),source:'OSRM',trafficAware:false,checkedAt:new Date().toISOString()},{headers:{'Cache-Control':'private, no-store'}});
 } catch {return Response.json({error:'Driving estimates are unavailable. Enter travel minutes manually, or check Google Maps and enter its traffic estimate.'},{status:503})}
}

return {POST};})();
const path=new URL(req.url).pathname.replace(/^.*\/functions\/v1\/planner/,'');
const fn=routes[path]?.[req.method];return fn?fn(req):Response.json({error:'Not found'},{status:404});
}

// This function verifies access tokens itself, including new publishable-key projects.
Deno.serve(async (request: Request)=>{
 const allowedOrigin=Deno.env.get('APP_ORIGIN');
 const origin=request.headers.get('origin');
 if(!allowedOrigin||origin!==allowedOrigin)return Response.json({error:'Origin not allowed'},{status:403});
 const cors={'Access-Control-Allow-Origin':allowedOrigin,'Access-Control-Allow-Headers':'authorization, apikey, content-type, x-client-info','Access-Control-Allow-Methods':'GET, POST, OPTIONS','Vary':'Origin','Cache-Control':'private, no-store'};
 const finish=(response: Response)=>{const headers=new Headers(response.headers);Object.entries(cors).forEach(([k,v])=>headers.set(k,v));return new Response(response.body,{status:response.status,headers})};
 if(request.method==='OPTIONS')return new Response(null,{status:204,headers:cors});
 const authorization=request.headers.get('authorization')||'';
 if(!authorization.startsWith('Bearer '))return finish(Response.json({error:'Sign in to access your planner.'},{status:401}));
 try{
  const client=createClient(Deno.env.get('SUPABASE_URL')!,Deno.env.get('SUPABASE_ANON_KEY')!,{global:{headers:{Authorization:authorization}},auth:{persistSession:false,autoRefreshToken:false}});
  const {data,error}=await client.auth.getUser(authorization.slice(7));
  if(error||!data.user)return finish(Response.json({error:'Please sign in again.'},{status:401}));
  // Bound request size even when Content-Length is missing. Avoid unbounded parsing.
  let req=request;
  if(!['GET','HEAD'].includes(request.method)){
   const reader=request.body?.getReader();const chunks=[];let length=0;
   if(reader){while(true){const {done,value}=await reader.read();if(done)break;length+=value.length;if(length>1500000){await reader.cancel();return finish(Response.json({error:'Planner is too large; export a backup.'},{status:413}))}chunks.push(value)}}
   const body=new Uint8Array(length);let offset=0;for(const chunk of chunks){body.set(chunk,offset);offset+=chunk.length}
   // The original handlers check same-origin. CORS above authenticates the browser origin;
   // use a canonical internal request origin so those checks keep the same contract.
   const headers=new Headers(request.headers);headers.set('origin',new URL(request.url).origin);req=new Request(request.url,{method:request.method,headers,body});
  }
  return finish(await dispatch(req,data.user,client));
 }catch{return finish(Response.json({error:'Unable to connect right now. Your device copy is safe.'},{status:503}))}
});
